/* @lc app=leetcode id=3297 lang=kotlin */ class Solution { fun ad(cnt: IntArray, need: IntArray, miss: IntArray, c: Int, d: Int) = (if (d > 0) cnt[c] + 1 <= need[c] else cnt[c] <= need[c]).let { if (it) miss[0] -= d }.also { cnt[c] += d } fun validSubstringCount(word1: String, word2: String): Long = IntArray(26).also { nd -> word2.forEach { nd[it - 'a']++ } }.let { need -> IntArray(26).let { cnt -> IntArray(1) { word2.length }.let { miss -> word1.indices.fold(0 to 0L) { (l, ans), r -> ad(cnt, need, miss, word1[r] - 'a', 1).let { generateSequence(l to ans) { (ll, aa) -> if (miss[0] == 0) (aa + (word1.length - r)).also { ad(cnt, need, miss, word1[ll] - 'a', -1) }.let { ll + 1 to it } else null }.last() } }.second } } } }